public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }
            if (String.isBlank(objectApiName)) {
                throw new SearchException('objectApiName cannot be blank.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('fields cannot be null or empty.');
            }

            Schema.DescribeSObjectResult objectDescribe = describeObject(objectApiName);
            if (objectDescribe == null) {
                throw new SearchException('Object not found: ' + objectApiName);
            }
            if (!objectDescribe.isAccessible() || !objectDescribe.isQueryable()) {
                throw new SearchException('Object not readable: ' + objectDescribe.getName());
            }

            Map<String, Schema.DescribeFieldResult> fieldsByApiName = describeFields(objectDescribe);

            List<String> selectFields = new List<String>{ 'Id' };
            Set<String> selectedFieldNames = new Set<String>{ 'id' };

            for (String requestedField : fields) {
                if (String.isBlank(requestedField)) {
                    throw new SearchException('Field name cannot be blank.');
                }

                Schema.DescribeFieldResult fieldDescribe = getField(fieldsByApiName, requestedField);
                if (fieldDescribe == null) {
                    throw new SearchException('Field not found: ' + requestedField);
                }
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('Field not accessible: ' + requestedField);
                }

                String apiName = fieldDescribe.getName();
                String key = apiName.toLowerCase();
                if (!selectedFieldNames.contains(key)) {
                    selectFields.add(apiName);
                    selectedFieldNames.add(key);
                }
            }

            String whereClause = '';
            if (filters != null && !filters.isEmpty()) {
                List<String> conditions = new List<String>();
                for (String filterField : filters.keySet()) {
                    if (String.isBlank(filterField)) {
                        throw new SearchException('Filter field name cannot be blank.');
                    }

                    Schema.DescribeFieldResult fieldDescribe = getField(fieldsByApiName, filterField);
                    if (fieldDescribe == null) {
                        throw new SearchException('Field not found: ' + filterField);
                    }
                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException('Field not filterable: ' + filterField);
                    }
                    if (!fieldDescribe.isAccessible()) {
                        throw new SearchException('Field not accessible: ' + filterField);
                    }

                    conditions.add(
                        fieldDescribe.getName() + ' = ' + toSoqlLiteral(fieldDescribe, filters.get(filterField))
                    );
                }
                whereClause = ' WHERE ' + String.join(conditions, ' AND ');
            }

            String orderByClause = '';
            if (!String.isBlank(orderByField)) {
                Schema.DescribeFieldResult fieldDescribe = getField(fieldsByApiName, orderByField);
                if (fieldDescribe == null) {
                    throw new SearchException('Field not found: ' + orderByField);
                }
                if (!fieldDescribe.isSortable()) {
                    throw new SearchException('Field not sortable: ' + orderByField);
                }
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('Field not accessible: ' + orderByField);
                }
                orderByClause = ' ORDER BY ' + fieldDescribe.getName() + ' ASC';
            }

            String query = 'SELECT ' + String.join(selectFields, ', ')
                + ' FROM ' + objectDescribe.getName();

            if (whereClause != '') {
                query += whereClause;
            }
            if (orderByClause != '') {
                query += orderByClause;
            }
            query += ' LIMIT ' + maxRows;

            return Database.query(query);
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }

    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        for (Schema.SObjectType objectType : Schema.getGlobalDescribe().values()) {
            Schema.DescribeSObjectResult describe = objectType.getDescribe();
            if (describe.getName().equalsIgnoreCase(objectApiName)) {
                return describe;
            }
        }
        return null;
    }

    private static Map<String, Schema.DescribeFieldResult> describeFields(Schema.DescribeSObjectResult objectDescribe) {
        Map<String, Schema.DescribeFieldResult> result = new Map<String, Schema.DescribeFieldResult>();
        for (Schema.SObjectField field : objectDescribe.getFields().values()) {
            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            result.put(fieldDescribe.getName().toLowerCase(), fieldDescribe);
        }
        return result;
    }

    private static Schema.DescribeFieldResult getField(Map<String, Schema.DescribeFieldResult> fieldsByApiName, String apiName) {
        return fieldsByApiName.get(apiName.toLowerCase());
    }

    private static String toSoqlLiteral(Schema.DescribeFieldResult fieldDescribe, Object value) {
        if (value == null) {
            return 'NULL';
        }
        if (value instanceof String) {
            return '\'' + String.escapeSingleQuotes((String) value) + '\'';
        }
        if (value instanceof Id) {
            return '\'' + String.escapeSingleQuotes(String.valueOf((Id) value)) + '\'';
        }
        if (value instanceof Boolean) {
            return String.valueOf((Boolean) value);
        }
        if (value instanceof Integer) {
            return String.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return String.valueOf((Long) value);
        }
        if (value instanceof Decimal) {
            return String.valueOf((Decimal) value);
        }
        if (value instanceof Date) {
            Date dateValue = (Date) value;
            String year = String.valueOf(dateValue.year());
            String month = String.valueOf(dateValue.month());
            String day = String.valueOf(dateValue.day());
            if (month.length() < 2) {
                month = '0' + month;
            }
            if (day.length() < 2) {
                day = '0' + day;
            }
            return year + '-' + month + '-' + day;
        }

        // Defensive fallback for unsupported UI value types.
        return '\'' + String.escapeSingleQuotes(String.valueOf(value)) + '\'';
    }
}
