public class OrderPayloadParser {
    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static Order parse(String body) {
        if (body == null || String.isBlank(body)) {
            throw new PayloadException('Body must not be null or blank.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON.');
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Body must be a JSON object.');
        }

        Map<String, Object> orderMap = (Map<String, Object>) root;

        String orderNumber = toText(orderMap.get('number'));
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Order number is missing or blank.');
        }

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = parseDate(orderMap.get('date'));
        order.currencyCode = toText(orderMap.get('currency'));

        Object customerObj = orderMap.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            order.customerEmail = toText(((Map<String, Object>) customerObj).get('email'));
        }

        order.lines = parseLines(orderMap.get('lines'));

        Decimal total = 0;
        for (Line line : order.lines) {
            total += line.lineTotal;
        }
        order.total = total;

        return order;
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order must not be null.');
        }

        return '{'
            + '"number":' + JSON.serialize(order.orderNumber)
            + ',"status":"RECEIVED"'
            + ',"lineCount":' + order.lines.size()
            + ',"total":' + JSON.serialize(order.total)
            + '}';
    }

    private static List<Line> parseLines(Object linesObj) {
        List<Line> lines = new List<Line>();

        if (!(linesObj instanceof List<Object>)) {
            return lines;
        }

        List<Object> linesList = (List<Object>) linesObj;
        for (Object lineObj : linesList) {
            if (!(lineObj instanceof Map<String, Object>)) {
                throw new PayloadException('Each line must be a JSON object.');
            }

            Map<String, Object> lineMap = (Map<String, Object>) lineObj;

            String sku = toText(lineMap.get('sku'));
            if (String.isBlank(sku)) {
                throw new PayloadException('Line sku is missing or blank.');
            }

            Integer quantity = toInteger(lineMap.get('quantity'));
            if (quantity == null || quantity <= 0) {
                throw new PayloadException('Line quantity must be positive.');
            }

            Decimal unitPrice = toDecimal(lineMap.get('unitPrice'));
            if (unitPrice == null || unitPrice < 0) {
                throw new PayloadException('Line unitPrice must be non-negative.');
            }

            Decimal discount = toDecimal(lineMap.get('discount'));
            if (discount == null) {
                discount = 0;
            }

            Decimal lineTotal = (unitPrice * quantity) * (1 - discount);
            lineTotal = lineTotal.setScale(2, RoundingMode.HALF_UP);

            Line line = new Line();
            line.sku = sku;
            line.quantity = quantity;
            line.unitPrice = unitPrice;
            line.discount = discount;
            line.lineTotal = lineTotal;

            lines.add(line);
        }

        return lines;
    }

    private static String toText(Object value) {
        if (value instanceof String) {
            return (String) value;
        }
        return null;
    }

    private static Date parseDate(Object value) {
        if (value instanceof String) {
            String dateStr = ((String) value).trim();
            if (String.isBlank(dateStr)) {
                return null;
            }
            try {
                return Date.valueOf(dateStr);
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }

    private static Integer toInteger(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Integer) {
            return (Integer) value;
        }
        if (value instanceof Long) {
            return ((Long) value).intValue();
        }
        if (value instanceof Decimal) {
            return ((Decimal) value).intValue();
        }
        if (value instanceof Double) {
            return ((Double) value).intValue();
        }
        if (value instanceof String) {
            String str = ((String) value).trim();
            if (String.isBlank(str)) {
                return null;
            }
            try {
                return Decimal.valueOf(str).intValue();
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer || value instanceof Long || value instanceof Double) {
            return Decimal.valueOf(String.valueOf(value));
        }
        if (value instanceof String) {
            String str = ((String) value).trim();
            if (String.isBlank(str)) {
                return null;
            }
            try {
                return Decimal.valueOf(str);
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }
}
