public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object API name and field API name are required.');
        }

        Schema.SObjectType sObjectType = findSObjectType(objectApiName);
        if (sObjectType == null) {
            throw new PicklistServiceException('Object not found: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe();
        Schema.DescribeFieldResult fieldDescribe = findFieldDescribe(objectDescribe, fieldApiName);
        if (fieldDescribe == null) {
            throw new PicklistServiceException('Field not found: ' + fieldApiName);
        }

        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.Picklist &&
            fieldType != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' + fieldApiName
            );
        }

        List<Option> options = new List<Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
            }
        }
        return options;
    }

    private static Schema.SObjectType findSObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    private static Schema.DescribeFieldResult findFieldDescribe(
        Schema.DescribeSObjectResult objectDescribe,
        String fieldApiName
    ) {
        Map<String, Schema.SObjectField> fields = objectDescribe.fields.getMap();
        for (String fieldName : fields.keySet()) {
            if (fieldName.equalsIgnoreCase(fieldApiName)) {
                return fields.get(fieldName).getDescribe();
            }
        }
        return null;
    }
}
