public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id cannot be null.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percent map cannot be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Decimal pct : percentByGauId.values()) {
            if (pct == null || pct <= 0) {
                throw new AllocationException('All percentages must be greater than zero.');
            }
            totalPercent += pct;
        }
        if (totalPercent > 100) {
            throw new AllocationException('Total percentages cannot exceed 100.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>(
            [SELECT Id, npsp__Active__c
             FROM npsp__General_Accounting_Unit__c
             WHERE Id IN :percentByGauId.keySet()]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU not found: ' + gauId);
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU is inactive: ' + gauId);
            }
        }

        List<Opportunity> opportunities = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            allocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        insert allocations;

        List<Id> allocationIds = new List<Id>();
        for (npsp__Allocation__c alloc : allocations) {
            allocationIds.add(alloc.Id);
        }

        return [
            SELECT Id, npsp__Opportunity__c, npsp__General_Accounting_Unit__c,
                   npsp__Amount__c, npsp__Percent__c, npsp__Payment__c,
                   npsp__Campaign__c, npsp__Recurring_Donation__c
            FROM npsp__Allocation__c
            WHERE Id IN :allocationIds
        ];
    }
}
