public with sharing class HouseholdService {
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        Id householdRecordTypeId = getHouseholdAccountRecordTypeId();

        // NPSP will rename the household once the primary contact is set.
        // A placeholder is required by the platform because Account.Name is mandatory.
        Account household = new Account(
            RecordTypeId = householdRecordTypeId,
            Name = 'Household'
        );
        insert household;

        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        household.npe01__One2OneContact__c = members.get(0).Id;
        update household;

        return household.Id;
    }

    private static Id getHouseholdAccountRecordTypeId() {
        Map<String, Schema.RecordTypeInfo> recordTypeInfos =
            Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName();
        Schema.RecordTypeInfo householdRecordTypeInfo = recordTypeInfos.get('HH_Account');
        if (householdRecordTypeInfo == null) {
            throw new IllegalArgumentException('HH_Account record type not found');
        }
        return householdRecordTypeInfo.getRecordTypeId();
    }
}
