public class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        List<Contact> contacts = [
            SELECT Id, AccountId, FirstName, LastName
            FROM Contact
            WHERE Id = :contactId
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        Contact contact = contacts[0];
        if (contact.AccountId == null) {
            throw new IllegalArgumentException('Contact does not belong to a household account.');
        }

        String opportunityName = buildOpportunityName(contact, giftDate);

        Opportunity gift = new Opportunity(
            Name = opportunityName,
            AccountId = contact.AccountId,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            Amount = amount,
            npsp__Primary_Contact__c = contactId
        );
        insert gift;

        ensureSinglePayment(gift.Id, amount, giftDate);

        List<npsp__Contact_Role__c> existingRoles = [
            SELECT Id, npsp__Contact__c, npsp__Role__c, npsp__Primary__c
            FROM npsp__Contact_Role__c
            WHERE npsp__Opportunity__c = :gift.Id
        ];

        Map<Id, List<npsp__Contact_Role__c>> rolesByContact = new Map<Id, List<npsp__Contact_Role__c>>();
        for (npsp__Contact_Role__c role : existingRoles) {
            if (!rolesByContact.containsKey(role.npsp__Contact__c)) {
                rolesByContact.put(role.npsp__Contact__c, new List<npsp__Contact_Role__c>());
            }
            rolesByContact.get(role.npsp__Contact__c).add(role);
        }

        List<npsp__Contact_Role__c> rolesToInsert = new List<npsp__Contact_Role__c>();
        List<npsp__Contact_Role__c> rolesToUpdate = new List<npsp__Contact_Role__c>();
        List<npsp__Contact_Role__c> rolesToDelete = new List<npsp__Contact_Role__c>();

        ensureRole(
            rolesByContact, contactId, 'Donor', true, gift.Id,
            rolesToInsert, rolesToUpdate, rolesToDelete
        );

        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :contact.AccountId
              AND Id != :contactId
            ORDER BY Id
        ];
        for (Contact member : householdMembers) {
            ensureRole(
                rolesByContact, member.Id, 'Household Member', false, gift.Id,
                rolesToInsert, rolesToUpdate, rolesToDelete
            );
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }

        return gift.Id;
    }

    private static String buildOpportunityName(Contact contact, Date giftDate) {
        String firstName = contact.FirstName == null ? '' : contact.FirstName.trim();
        String lastName = contact.LastName == null ? '' : contact.LastName.trim();
        String fullName = (firstName + ' ' + lastName).trim();
        String dateString = String.valueOf(giftDate.year()).leftPad(4, '0') + '-' +
            String.valueOf(giftDate.month()).leftPad(2, '0') + '-' +
            String.valueOf(giftDate.day()).leftPad(2, '0');
        if (fullName.length() > 0) {
            return fullName + ' Donation ' + dateString;
        }
        return 'Donation ' + dateString;
    }

    private static void ensureSinglePayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate
        ];

        if (payments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
        } else {
            npe01__OppPayment__c payment = payments[0];
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            update payment;

            if (payments.size() > 1) {
                List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < payments.size(); i++) {
                    extras.add(payments[i]);
                }
                delete extras;
            }
        }
    }

    private static void ensureRole(
        Map<Id, List<npsp__Contact_Role__c>> rolesByContact,
        Id contactId,
        String roleName,
        Boolean isPrimary,
        Id opportunityId,
        List<npsp__Contact_Role__c> rolesToInsert,
        List<npsp__Contact_Role__c> rolesToUpdate,
        List<npsp__Contact_Role__c> rolesToDelete
    ) {
        List<npsp__Contact_Role__c> roles = rolesByContact.get(contactId);
        if (roles == null || roles.isEmpty()) {
            rolesToInsert.add(new npsp__Contact_Role__c(
                npsp__Contact__c = contactId,
                npsp__Opportunity__c = opportunityId,
                npsp__Role__c = roleName,
                npsp__Primary__c = isPrimary
            ));
        } else {
            npsp__Contact_Role__c keep = roles[0];
            if (keep.npsp__Role__c != roleName || keep.npsp__Primary__c != isPrimary) {
                keep.npsp__Role__c = roleName;
                keep.npsp__Primary__c = isPrimary;
                rolesToUpdate.add(keep);
            }
            if (roles.size() > 1) {
                for (Integer i = 1; i < roles.size(); i++) {
                    rolesToDelete.add(roles[i]);
                }
            }
        }
    }
