public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String CLOSED_WON = 'Closed Won';
    private static final Decimal MIN_GIFT_AMOUNT = 5000;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<Task> tasks = new List<Task>();

        if (newlist == null || newlist.isEmpty()) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        Map<Id, SObject> oldById = new Map<Id, SObject>();
        if (oldlist != null) {
            for (SObject oldRec : oldlist) {
                oldById.put(oldRec.Id, oldRec);
            }
        }

        for (SObject newRec : newlist) {
            Opportunity opp = (Opportunity) newRec;

            if (!isQualifiedGift(opp)) {
                continue;
            }

            Opportunity oldOpp = (Opportunity) oldById.get(opp.Id);
            if (oldOpp != null && isQualifiedGift(oldOpp)) {
                continue;
            }

            Task task = new Task(
                Subject = 'Major gift thank-you call',
                Priority = 'High',
                Status = 'Not Started',
                WhatId = opp.Id,
                WhoId = opp.npsp__Primary_Contact__c,
                OwnerId = opp.OwnerId,
                ActivityDate = opp.CloseDate.addDays(3)
            );
            tasks.add(task);
        }

        npsp.TDTM_Runnable.DmlWrapper wrapper = new npsp.TDTM_Runnable.DmlWrapper();
        for (Task task : tasks) {
            wrapper.dmlObjects.add(task);
        }

        return wrapper;
    }

    private static Boolean isQualifiedGift(Opportunity opp) {
        return opp.StageName == CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MIN_GIFT_AMOUNT;
    }
}
