public inherited sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                candidates.add(c);
                accountIds.add(c.AccountId);
                emails.add(normalizeEmail(c.Email));
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        Set<String> occupiedPairs = new Set<String>();
        for (Contact existing : queryExistingContacts(accountIds, emails)) {
            if (existing.AccountId != null && String.isNotBlank(existing.Email)) {
                occupiedPairs.add(pairKey(existing.AccountId, existing.Email));
            }
        }

        processCandidates(candidates, occupiedPairs);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact newC = (Contact) triggerNew[i];
            Contact oldC = (Contact) triggerOld[i];
            if (newC.AccountId != null && String.isNotBlank(newC.Email) && isChanged(newC, oldC)) {
                candidates.add(newC);
                accountIds.add(newC.AccountId);
                emails.add(normalizeEmail(newC.Email));
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        Set<String> occupiedPairs = new Set<String>();
        for (Contact existing : queryExistingContacts(accountIds, emails)) {
            if (existing.AccountId != null && String.isNotBlank(existing.Email)) {
                occupiedPairs.add(pairKey(existing.AccountId, existing.Email));
            }
        }

        processCandidates(candidates, occupiedPairs);
    }

    private List<Contact> queryExistingContacts(Set<Id> accountIds, Set<String> emails) {
        return [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND LOWER(Email) IN :emails
        ];
    }

    private void processCandidates(List<Contact> candidates, Set<String> occupiedPairs) {
        for (Contact c : candidates) {
            String key = pairKey(c.AccountId, c.Email);
            if (occupiedPairs.contains(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                occupiedPairs.add(key);
            }
        }
    }

    private Boolean isChanged(Contact newC, Contact oldC) {
        if (newC.AccountId != oldC.AccountId) {
            return true;
        }
        return normalizeEmail(newC.Email) != normalizeEmail(oldC.Email);
    }

    private String normalizeEmail(String email) {
        return email == null ? '' : email.toLowerCase();
    }

    private String pairKey(Id accountId, String email) {
        return accountId + ':' + normalizeEmail(email);
    }
}
